int passed=0,failed=0;
void Check(string name,Action test){try{test();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
void Must(bool condition){if(!condition)throw new Exception("Expected condition not met");}
CastleMobTargetAccessTests.Run(Check,Must);
Check("Slime unbounded camera uses full wall extent without a 400048-region floor",()=>{Must(CastleCollisionBounds.TryAxis(-100000,100000,10,true,-61.57786560058594,59.037322998046875,.5,out var min,out var max));Must(min==-62.07786560058594&&max==59.537322998046875);int regions=((int)Math.Floor((max/.5+377856)/8)-(int)Math.Floor((min/.5+377856)/8)+1)*8;Must(regions==248);});
