Check("Finite room camera bounds remain exactly unchanged",()=>{Must(CastleCollisionBounds.TryAxis(-12,15,10,false,0,0,.5,out var min,out var max));Must(min==-22&&max==25);Must(CastleCollisionBounds.TryAxis(1,4.77,6,false,0,0,.3,out min,out max));Must(min==-5&&Math.Abs(max-10.77)<1e-10);});
