Check("Chest opens onto a distinct native frame without reusing closed-frame UV dimensions",()=>{Must(CastleChestFrames.Resolve("bossChest_2",262,136)==CastleChestFrame.ClosedLid);Must(CastleChestFrames.Resolve("bossChest_1",249,125)==CastleChestFrame.OpenedLid);Must(CastleChestFrames.Resolve("bossChest_1",262,136)==CastleChestFrame.Unknown);Must(CastleChestFrames.Resolve("other",249,125)==CastleChestFrame.Unknown);});
Check("Native closed and opened cap pivots retain their actual body-relative offsets",()=>{Must(CastleChestFrames.TryNativeOffset(CastleChestFrame.ClosedLid,0,.64,126,66.5,131,68,100,out var x,out var y)&&Math.Abs(x+5)<1e-6&&Math.Abs(y-62.5)<1e-6);Must(CastleChestFrames.TryNativeOffset(CastleChestFrame.OpenedLid,0,1.205,126,66.5,124.5,62.5,100,out x,out y)&&Math.Abs(x-1.5)<1e-6&&Math.Abs(y-124.5)<1e-6);Must(!CastleChestFrames.TryNativeOffset(CastleChestFrame.Unknown,0,1,126,66.5,124.5,62.5,100,out x,out y));});
Check("Chest lid shell joins the native body anchor without texture-size offset",()=>{var pixels=new uint[262*136];Array.Fill(pixels,0xFF448855u);var skin=CastleChestSkin.Build(pixels,262,136,100,0,0,default);double minY=double.MaxValue;int count=0;foreach(var v in skin.Vertices)if(v.NX!=0){count++;minY=Math.Min(minY,v.Y);Must(Math.Abs((v.X-.05)-.44)<1e-6||Math.Abs((v.X-.05)-2.08)<1e-6);}Must(count>0&&Math.Abs(minY+.625-1.26)<1e-6);});
Check("Chest front is continuous and retains native pixel coordinates",()=>{var pixels=new uint[252*133];Array.Fill(pixels,0xFF448855u);var skin=CastleChestSkin.Build(pixels,252,133,100,126,66.5,default);Must(skin.FrontVertexCount>0);for(int i=0;i<skin.FrontVertexCount;i++){var v=skin.Vertices[i];Must(v.NZ==-1&&Math.Abs(v.Z+.8)<1e-6);Must(Math.Abs((v.X*100+126)/252-v.U)<1e-6&&Math.Abs((v.Y*100+66.5)/133-v.V)<1e-6);}});
Check("Chest side UVs cover native regions instead of collapsed single texels",()=>{var pixels=new uint[252*133];Array.Fill(pixels,0xFF448855u);var skin=CastleChestSkin.Build(pixels,252,133,100,0,0,default);for(int i=skin.FrontVertexCount;i<skin.Vertices.Length;i+=4){var a=skin.Vertices[i];var b=skin.Vertices[i+1];var d=skin.Vertices[i+3];Must(Math.Abs(a.U-b.U)>1e-5&&Math.Abs(a.V-d.V)>1e-5);double physicalU=Math.Sqrt(Math.Pow(a.X-b.X,2)+Math.Pow(a.Y-b.Y,2)+Math.Pow(a.Z-b.Z,2))*100;Must(Math.Abs(physicalU-Math.Abs(a.U-b.U)*252)<1e-4);}});
Check("Chest metal frame has depth and closed panel connectors",()=>{var pixels=new uint[252*133];Array.Fill(pixels,0xFF448855u);var skin=CastleChestSkin.Build(pixels,252,133,100,0,0,default);bool recessed=false,closed=false;for(int i=skin.FrontVertexCount;i<skin.Vertices.Length;i+=4){var a=skin.Vertices[i];var d=skin.Vertices[i+3];if(a.NX==-1&&Math.Abs(a.X-.46)<1e-6)recessed=true;if(a.NZ==-1&&Math.Abs(a.X-.44)<1e-6&&Math.Abs(d.X-.46)<1e-6)closed=true;}Must(recessed&&closed);});
Check("Chest profile rejects a different sprite rather than assigning wrong UVs",()=>{bool rejected=false;try{CastleChestSkin.Build(new uint[64],8,8,100,0,0,default);}catch(ArgumentException){rejected=true;}Must(rejected);});
Check("Look extension fits reserved v11 state",()=>{Must(System.Runtime.InteropServices.Marshal.OffsetOf<Proto.GuestState>("lookAck").ToInt32()==0xC8);Must(System.Runtime.InteropServices.Marshal.SizeOf<Proto.GuestState>()<=256);});
Check("Unacknowledged look displays immediately and retires exactly once",()=>{var l=new CastleLook();uint a=l.Add(10,0);l.Resolve(0,0,0,.5f,4,out var y,out _);Must(Math.Abs(y-1.5)<.00001);l.Resolve(1.5f,0,a,.5f,4,out y,out _);Must(y==1.5f);});
Check("Look ack retains later opposite input",()=>{var l=new CastleLook();uint a=l.Add(10,0);l.Add(-4,0);l.Resolve(1.5f,0,a,.5f,4,out var y,out _);Must(Math.Abs(y-.9)<.00001);});
