Check("Scope smooth camera legacy and reset retain native policy",()=>{var l=new CastleLook();l.Add(80,0);l.Resolve(0,0,0,.5f,68,out var y,out _);Must(Math.Abs(y-1.5)<.00001);l.Resolve(3,4,0,.5f,36,out y,out var p);Must(y==3&&p==4);l.Resolve(3,4,0,.5f,0,out y,out p);Must(y==3&&p==4);l.Reset();l.Resolve(3,4,0,.5f,4,out y,out p);Must(y==3&&p==4);});
Check("Authored first-person cuboids have volume on all three axes",()=>{Must(CastleCuboidLibrary.Models.Count==15);foreach(var model in CastleCuboidLibrary.Models.Values)foreach(var e in model)Must(e.Valid);});
