Check("Packed rotated native sprite preserves pivot and independent UV axes",()=>{var v=new[]{new CastleSpriteVertex(-.35,-.2,.375,.5),new CastleSpriteVertex(.65,-.2,.375,.75),new CastleSpriteVertex(.65,.8,.25,.75),new CastleSpriteVertex(-.35,.8,.25,.5)};Must(CastleSpriteUv.TryCreate(v,new[]{0,1,2,0,2,3},out var map));map!.Map(-.1,.4,out var u,out var w);Must(Math.Abs(u-.3)<1e-8&&Math.Abs(w-.5625)<1e-8);Must(Math.Abs(map.PixelDensityX(512,256)-64)<1e-8&&Math.Abs(map.PixelDensityY(512,256)-64)<1e-8);});
Check("Tight sprite mask rejects adjacent atlas image inside its rectangle",()=>{Must(CastleSpriteUv.TryCreate(new[]{new CastleSpriteVertex(0,0,.2,.2),new CastleSpriteVertex(1,0,.4,.2),new CastleSpriteVertex(0,1,.2,.4)},new[]{0,1,2},out var map));Must(map!.TryTexel(.25,.25,100,100,out var i)&&i==2525);Must(!map.TryTexel(.9,.9,100,100,out i)&&i==-1);});
Check("Mirrored native atlas uses true mapping rather than a swapped bounding box",()=>{Must(CastleSpriteUv.TryCreate(new[]{new CastleSpriteVertex(0,0,.7,.1),new CastleSpriteVertex(1,0,.5,.1),new CastleSpriteVertex(0,1,.7,.3)},new[]{0,1,2},out var map));map!.Map(.25,.25,out var u,out var v);Must(Math.Abs(u-.65)<1e-8&&Math.Abs(v-.15)<1e-8);});
Check("Invalid nonaffine native UV and broken triangles fail closed",()=>{Must(!CastleSpriteUv.TryCreate(new[]{new CastleSpriteVertex(0,0,0,0),new CastleSpriteVertex(1,0,1,0),new CastleSpriteVertex(0,1,0,1),new CastleSpriteVertex(1,1,.2,.2)},new[]{0,1,2,1,3,2},out _));Must(!CastleSpriteUv.TryCreate(new[]{new CastleSpriteVertex(0,0,0,0),new CastleSpriteVertex(1,0,1,0),new CastleSpriteVertex(0,1,0,1)},new[]{0,1,9},out _));});
Check("Single native texel keeps original alpha sample and does not stretch atlas neighbors",()=>{Must(CastleSpriteUv.TryCreate(new[]{new CastleSpriteVertex(0,0,.25,.25),new CastleSpriteVertex(1,0,.25,.25),new CastleSpriteVertex(0,1,.25,.25)},new[]{0,1,2},out var map));Must(map!.TryTexel(.2,.2,8,8,out var i)&&i==18&&map.PixelDensityX(8,8)==0);});
Check("Native pixel copy preserves exact RGBA and excludes adjacent opaque sprite",()=>{Must(CastleSpriteUv.TryCreate(new[]{new CastleSpriteVertex(0,0,.25,.25),new CastleSpriteVertex(1,0,.75,.25),new CastleSpriteVertex(0,1,.25,.75)},new[]{0,1,2},out var map));var source=new uint[16];source[5]=0x80302010u;source[6]=0x000A0B0Cu;source[9]=0xFFABCDEFu;source[10]=0xFF0000FFu;var copy=CastleSpritePixels.Unpack(map!,2,2,0,0,2,source,4,4,null,0,0,default);Must(copy.Pixels[0]==source[5]&&copy.Pixels[1]==source[6]&&copy.Pixels[2]==source[9]&&copy.Pixels[3]==0);Must(copy.Alpha[0]==128&&copy.Alpha[1]==0&&copy.Alpha[2]==255&&copy.Alpha[3]==0&&copy.Translucent&&source[10]==0xFF0000FFu);});
Check("Native split alpha changes only actual alpha and preserves source RGB",()=>{Must(CastleSpriteUv.TryCreate(new[]{new CastleSpriteVertex(0,0,.25,.25),new CastleSpriteVertex(1,0,.75,.25),new CastleSpriteVertex(0,1,.25,.75)},new[]{0,1,2},out var map));var source=new uint[16];source[5]=0xFF302010u;var split=new uint[16];split[5]=32;var copy=CastleSpritePixels.Unpack(map!,2,2,0,0,2,source,4,4,split,4,4,default);Must(copy.Pixels[0]==0x20302010u&&copy.Alpha[0]==32&&source[5]==0xFF302010u);});
Check("Cancelled native texture job stops instead of publishing an old room",()=>{Must(CastleSpriteUv.TryCreate(new[]{new CastleSpriteVertex(0,0,0,0),new CastleSpriteVertex(1,0,1,0),new CastleSpriteVertex(0,1,0,1)},new[]{0,1,2},out var map));var cancellation=new System.Threading.CancellationTokenSource();cancellation.Cancel();bool stopped=false;try{CastleSpritePixels.Unpack(map!,2,2,0,0,2,new uint[4],2,2,null,0,0,cancellation.Token);}catch(OperationCanceledException){stopped=true;}finally{cancellation.Dispose();}Must(stopped);});
Check("Native voxel preserves one physical pixel per front UV and has real depth",()=>{var pixels=new uint[64];Array.Fill(pixels,0xFF448855u);var skin=CastleVoxelSkin.Build(pixels,8,8,100,4,4,.08,true,default);Must(skin.Vertices.Length>0&&skin.Opaque.Length>0&&skin.Blended.Length==0);Must(skin.HalfDepthAt(0,0)>skin.HalfDepthAt(-.035,-.035));foreach(var v in skin.Vertices)if(v.NZ==-1)Must(Math.Abs((v.X*100+4)/8-v.U)<1e-6&&Math.Abs((v.Y*100+4)/8-v.V)<1e-6);});
