Check("Opaque native voxel pixels write depth separately from actual soft pixels",()=>{var pixels=new[]{0xFF448855u,0x80448855u};var skin=CastleVoxelSkin.Build(pixels,2,1,100,0,0,.02,true,default);Must(skin.Opaque.Length>0&&skin.Blended.Length>0);foreach(int j in skin.Opaque)Must(j>=0&&j<skin.Vertices.Length);foreach(int j in skin.Blended)Must(j>=0&&j<skin.Vertices.Length);});
Check("Native voxel backside sample is an original pixel and normals never cancel",()=>{var pixels=new uint[64];Array.Fill(pixels,0xFF448855u);pixels[0]=0xFFFFFFFFu;var skin=CastleVoxelSkin.Build(pixels,8,8,100,4,4,.08,true,default);Must(pixels[skin.BackSample]==0xFF448855u);foreach(var v in skin.Vertices)Must(Math.Abs(v.NX*v.NX+v.NY*v.NY+v.NZ*v.NZ-1)<1e-6);});
Check("Cancelled voxel build stops before uploading stale scene geometry",()=>{var token=new System.Threading.CancellationTokenSource();token.Cancel();bool stopped=false;try{CastleVoxelSkin.Build(new uint[]{0xFFFFFFFFu},1,1,100,0,0,.01,true,token.Token);}catch(OperationCanceledException){stopped=true;}finally{token.Dispose();}Must(stopped);});
