Check("Door roof cannot pass as same-floor arrival",()=>Must(!Accepted(y:2.5,sy:2.5)));
Check("Far or nonfinite arrival cannot teleport the hero",()=>Must(!Accepted(x:13315,sx:13315)&&!Accepted(y:double.NaN)));
Check("External forces are bounded without synthetic damage",()=>Must(CastleExternalMotion.Valid(.15,.2)&&!CastleExternalMotion.Valid(1,0)&&!CastleExternalMotion.Valid(double.NaN,0)));
Check("Stale actor origins reject external forces",()=>Must(CastleExternalMotion.ValidOrigin(65536,-8,65537,-8)&&!CastleExternalMotion.ValidOrigin(65536,-8,65540,-8)));
Check("Host protocol sizes and offsets match v11",()=>Must(Proto.SelfCheck(new ManualLogSource("CastleCraft host regression"))));
Check("Busy writer retains the previous complete guest pose",()=>{
 unsafe{Proto.GuestState slot=new(){seq=1,x=0,yaw=0},previous=new(){x=65536,y=32,yaw=155,flags=1};
 Must(!Rings.SeqlockUpdate((byte*)&slot,ref previous));Must(previous.x==65536&&previous.y==32&&previous.yaw==155&&previous.flags==1);}
});
Check("Completed writer replaces the retained pose atomically",()=>{
 unsafe{Proto.GuestState slot=new(){seq=2,x=65537,y=33,yaw=160,flags=5},previous=default;
 Must(Rings.SeqlockUpdate((byte*)&slot,ref previous));Must(previous.x==65537&&previous.y==33&&previous.yaw==160&&previous.flags==5);}
});
Check("Shared render partial continues without a second time origin",()=>{
 var state=new Proto.GuestState{x=65536.4,y=32,z=0,prevX=65536,curX=65537,prevY=32,curY=32,tickQpc=1000,tickMs=50};
 CastlePose.Sample(state,1020,1000,out var x,out var y,out _);Must(Math.Abs(x-state.x)<1e-8&&y==32);
 CastlePose.Sample(state,1025,1000,out x,out _,out _);Must(Math.Abs(x-65536.5)<1e-8);
});
Check("Render interpolation stops at the latest physics tick",()=>{
 var state=new Proto.GuestState{x=5,prevX=4,curX=5,tickQpc=1000,tickMs=50};
 CastlePose.Sample(state,1100,1000,out var x,out _,out _);Must(x==5);
});
Check("Old or incompatible pose samples keep published render feet",()=>{
 var state=new Proto.GuestState{x=65536,y=32,prevX=0,curX=1,tickQpc=1000,tickMs=50};
 CastlePose.Sample(state,1025,1000,out var x,out var y,out _);Must(x==65536&&y==32);
 CastlePose.Sample(state,1500,1000,out x,out y,out _);Must(x==65536&&y==32);
});
Check("Native restraint routes alternating held directions and releases prior movement",()=>{
 var route=new CastleStruggleInput();var sent=new System.Collections.Generic.List<string>();int released=0;
 route.Update(true,true,false,()=>released++,sent.Add);route.Update(true,true,false,()=>released++,sent.Add);route.Update(true,false,true,()=>released++,sent.Add);
 Must(released==1&&string.Join(",",sent)=="Left,Left,Right");
});
Check("Ending restraint stops native dispatch and releases once before normal input resumes",()=>{
 var route=new CastleStruggleInput();int released=0,calls=0;
 route.Update(true,true,false,()=>released++,_=>calls++);route.Update(false,true,true,()=>released++,_=>calls++);route.Update(false,true,true,()=>released++,_=>calls++);
 Must(released==2&&calls==1);
});
Check("Temporary native IsAlive false with positive HP is not death",()=>Must(CastleLifeGate.Evaluate(false,false,10,false,false,false,20)==CastleLifeTransition.Wait));
Check("Zero native HP triggers death before IsAlive replication",()=>Must(CastleLifeGate.Evaluate(false,true,0,true,true,false,20)==CastleLifeTransition.NativeDeath));
Check("Native revival supersedes unacknowledged death without ownership",()=>Must(CastleLifeGate.Evaluate(true,true,25,false,true,false,0)==CastleLifeTransition.NativeRevival));
Check("Shared death waits for native revival despite independent Minecraft respawn",()=>Must(CastleLifeGate.Evaluate(true,false,0,false,true,true,20)==CastleLifeTransition.Wait));
Check("Acknowledged Minecraft death enters native death pipeline",()=>Must(CastleLifeGate.Evaluate(false,true,50,true,true,true,0)==CastleLifeTransition.GuestDeath));
Check("Stale Minecraft zero HP cannot rekill a pending native revival",()=>Must(CastleLifeGate.Evaluate(false,true,50,true,true,false,0)==CastleLifeTransition.Wait));
Check("Suspended live hero retains native health authority",()=>Must(CastleLifeGate.Evaluate(false,true,50,false,true,true,0)==CastleLifeTransition.Wait));
Check("Live acknowledged guest mirrors health",()=>Must(CastleLifeGate.Evaluate(false,true,50,true,true,true,10)==CastleLifeTransition.Mirror));
Check("Life sequences are distinct for same-frame death and revival",()=>Must(CastleLifeGate.NextSequence(0)==1&&CastleLifeGate.NextSequence(1)==2&&CastleLifeGate.NextSequence(int.MaxValue)==1));
Check("Unconfirmed transition zero HP cannot kill Minecraft",()=>Must(CastleLifeGate.Evaluate(false,false,0,false,true,true,20,false)==CastleLifeTransition.Wait));
Check("Confirmed gameplay native zero HP still shares death",()=>Must(CastleLifeGate.Evaluate(false,false,0,false,true,true,20,true)==CastleLifeTransition.NativeDeath));
Check("First life command begins with valid nonzero sequence",()=>Must(CastleLifeGate.NextSequence(0)==1));
Check("Actor discovery never scans two types in the same frame",()=>{var scan=new CastleActorScanSchedule();for(int i=0;i<6;i++){Must(scan.Take(i*.003f,10+i,6)==i);Must(scan.Take(i*.003f,10+i,6)==-1);}Must(scan.Take(.9f,200,6)==-1);Must(scan.Take(1f,300,6)==0);});
Check("Discovery reset cancels partial old-room sweep",()=>{var scan=new CastleActorScanSchedule();Must(scan.Take(10,1,6)==0);Must(scan.Take(10,2,6)==1);scan.Reset();Must(scan.Take(10,3,6)==0);});
Check("Low FPS still completes a sweep without restarting midway",()=>{var scan=new CastleActorScanSchedule();for(int i=0;i<6;i++)Must(scan.Take(i,10+i,6)==i);Must(scan.Take(6,16,6)==0);Must(scan.Take(7,17,0)==-1);});
var output=args.Length>0?args[0]:"host-test-results.json";
File.WriteAllText(output,JsonSerializer.Serialize(new{tests=passed+failed,passed,failures=failed},new JsonSerializerOptions{WriteIndented=true}));
Console.WriteLine($"HOST TESTS: {passed} passed, {failed} failed");
return failed==0?0:1;
